#include <stdio.h>
#include <sys/ioctl.h>
#include <linux/ppdev.h>
#include <linux/parport.h>

int main() {
    printf("PPSETMODE = 0x%x\n", PPSETMODE);
    printf("PPRSTATUS = 0x%x\n", PPRSTATUS);
    printf("PPRCONTROL = 0x%x\n", PPRCONTROL);
    printf("PPWCONTROL = 0x%x\n", PPWCONTROL);
    printf("PPFCONTROL = 0x%x\n", PPFCONTROL);
    printf("PPRDATA = 0x%x\n", PPRDATA);
    printf("PPWDATA = 0x%x\n", PPWDATA);
    printf("PPRFIFO = 0x%x\n", PPRFIFO);
    printf("PPWFIFO = 0x%x\n", PPWFIFO);
    printf("PPCLAIM = 0x%x\n", PPCLAIM);
    printf("PPRELEASE = 0x%x\n", PPRELEASE);
    printf("PPYIELD = 0x%x\n", PPYIELD);
    printf("PPEXCL = 0x%x\n", PPEXCL);
    printf("PPDATADIR = 0x%x\n", PPDATADIR);
    printf("PPNEGOT = 0x%x\n", PPNEGOT);
    printf("PPWCTLONIRQ = 0x%x\n", PPWCTLONIRQ);
    printf("PPCLRIRQ = 0x%x\n", PPCLRIRQ);
    printf("PPSETPHASE = 0x%x\n", PPSETPHASE);
    printf("PPGETTIME = 0x%x\n", PPGETTIME);
    printf("PPSETTIME = 0x%x\n", PPSETTIME);
    printf("PPGETMODES = 0x%x\n", PPGETMODES);
    printf("PPGETMODE = 0x%x\n", PPGETMODE);
    printf("PPGETPHASE = 0x%x\n", PPGETPHASE);
    printf("PPGETFLAGS = 0x%x\n", PPGETFLAGS);
    printf("PPSETFLAGS = 0x%x\n", PPSETFLAGS);

    printf("\n/* Flags */\n");
    printf("PP_FASTWRITE = 0x%x\n", PP_FASTWRITE);
    printf("PP_FASTREAD = 0x%x\n", PP_FASTREAD);
    printf("PP_W91284PIC = 0x%x\n", PP_W91284PIC);

    printf("\n/* Parport control lines */\n");
    printf("PARPORT_CONTROL_STROBE = 0x%x\n", PARPORT_CONTROL_STROBE);
    printf("PARPORT_CONTROL_AUTOFD = 0x%x\n", PARPORT_CONTROL_AUTOFD);
    printf("PARPORT_CONTROL_INIT = 0x%x\n", PARPORT_CONTROL_INIT);
    printf("PARPORT_CONTROL_SELECT = 0x%x\n", PARPORT_CONTROL_SELECT);

    printf("\n/* Parport status lines */\n");
    printf("PARPORT_STATUS_ERROR = 0x%x\n", PARPORT_STATUS_ERROR);
    printf("PARPORT_STATUS_SELECT = 0x%x\n", PARPORT_STATUS_SELECT);
    printf("PARPORT_STATUS_PAPEROUT = 0x%x\n", PARPORT_STATUS_PAPEROUT);
    printf("PARPORT_STATUS_ACK = 0x%x\n", PARPORT_STATUS_ACK);
    printf("PARPORT_STATUS_BUSY = 0x%x\n", PARPORT_STATUS_BUSY);

    printf("\n/* IEEE1284 modes */\n");
    printf("IEEE1284_MODE_NIBBLE = 0x%x\n", IEEE1284_MODE_NIBBLE);
    printf("IEEE1284_MODE_BYTE = 0x%x\n", IEEE1284_MODE_BYTE);
    printf("IEEE1284_MODE_COMPAT = 0x%x\n", IEEE1284_MODE_COMPAT);
    printf("IEEE1284_MODE_ECP = 0x%x\n", IEEE1284_MODE_ECP);
    printf("IEEE1284_MODE_ECPRLE = 0x%x\n", IEEE1284_MODE_ECPRLE);
    printf("IEEE1284_MODE_EPP = 0x%x\n", IEEE1284_MODE_EPP);

    printf("\n/* Parport modes */\n");
    printf("PARPORT_MODE_PCSPP = 0x%x\n", PARPORT_MODE_PCSPP);
    printf("PARPORT_MODE_TRISTATE = 0x%x\n", PARPORT_MODE_TRISTATE);
    printf("PARPORT_MODE_EPP = 0x%x\n", PARPORT_MODE_EPP);
    printf("PARPORT_MODE_ECP = 0x%x\n", PARPORT_MODE_ECP);
    printf("PARPORT_MODE_COMPAT = 0x%x\n", PARPORT_MODE_COMPAT);
    printf("PARPORT_MODE_DMA = 0x%x\n", PARPORT_MODE_DMA);

    return 0;
}
EOF
gcc /tmp/ppdev_extract.c -o /tmp/ppdev_extract && /tmp/ppdev_extract

